SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='cdfa190f-3235-5c98-b217-bf27a5d03d66'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('ebc5b1de-0496-567d-820a-12499c92d32d','278d1f31-f45c-5520-badc-b6811c6f5462')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='cdfa190f-3235-5c98-b217-bf27a5d03d66'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='cdfa190f-3235-5c98-b217-bf27a5d03d66'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('ebc5b1de-0496-567d-820a-12499c92d32d','278d1f31-f45c-5520-badc-b6811c6f5462')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='cdfa190f-3235-5c98-b217-bf27a5d03d66'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
