  AND q.result_body='{"contract":"SH-004.v1","requestId":"app-write-two-genuine-sh004","status":"ok","value":{"customerProfileId":"cdfa190f-3235-5c98-b217-bf27a5d03d66","userId":"8136b2ae-cea6-5c8d-a04e-9bd70784c943","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"ebc5b1de-0496-567d-820a-12499c92d32d","semanticKey":"customer-controls-app-write-two-genuine-sh004","fingerprint":"c4fdd595f8bee058923d096f94b21b2a18f87bf64d2836fd162ba4be218fa446","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='d819bc18-7905-556e-bf07-4f21f62362a0' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='236df9dc-6084-5d71-8e7e-a97919fa2b21' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"cdfa190f-3235-5c98-b217-bf27a5d03d66"},"prior":null,"committed":{"id":"cdfa190f-3235-5c98-b217-bf27a5d03d66","userId":"8136b2ae-cea6-5c8d-a04e-9bd70784c943","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='cdfa190f-3235-5c98-b217-bf27a5d03d66' AND c.user_id='8136b2ae-cea6-5c8d-a04e-9bd70784c943' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
